// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *Insurance) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *Insurance) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var noVal types.Code
		if v, exists := pkMap["no"]; exists {
			switch val := v.(type) {
			case types.Code:
				noVal = val
			case string:
				noVal = types.NewCode(val)
			}
		}
		return t.GetByPK(noVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case types.Code:
		return t.GetByPK(pk)
	case string:
		return t.GetByPK(types.NewCode(pk))
	}

	fmt.Printf("Error: Invalid primary key type for Insurance.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *Insurance) GetByPK(no types.Code) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)
	var noNull sql.NullString
	var effective_dateNull sql.NullString
	var policy_noNull sql.NullString
	var annual_premiumNull sql.NullString
	var policy_coverageNull sql.NullString
	var insurance_typeNull sql.NullString
	var last_date_modifiedNull sql.NullString
	var insurance_vendor_noNull sql.NullString
	var fa_class_codeNull sql.NullString
	var fa_subclass_codeNull sql.NullString
	var fa_location_codeNull sql.NullString
	var department_codeNull sql.NullString
	var project_codeNull sql.NullString
	var location_codeNull sql.NullString
	var blockedBool sql.NullBool
	var descriptionNull sql.NullString
	var search_descriptionNull sql.NullString
	var no_seriesNull sql.NullString

	// Collect arguments for query
	args := []interface{}{
		no,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT no, effective_date, policy_no, annual_premium, policy_coverage, insurance_type, last_date_modified, insurance_vendor_no, fa_class_code, fa_subclass_code, fa_location_code, department_code, project_code, location_code, blocked, description, search_description, no_series FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&noNull,
		&effective_dateNull,
		&policy_noNull,
		&annual_premiumNull,
		&policy_coverageNull,
		&insurance_typeNull,
		&last_date_modifiedNull,
		&insurance_vendor_noNull,
		&fa_class_codeNull,
		&fa_subclass_codeNull,
		&fa_location_codeNull,
		&department_codeNull,
		&project_codeNull,
		&location_codeNull,
		&blockedBool,
		&descriptionNull,
		&search_descriptionNull,
		&no_seriesNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Insurance: %v\n", err)
		return false
	}

	// Populate fields
	t.No = types.NewCode(noNull.String)
	t.Effective_date, _ = types.NewDateFromString(effective_dateNull.String)
	t.Policy_no = types.NewText(policy_noNull.String)
	t.Annual_premium, _ = types.NewDecimalFromString(annual_premiumNull.String)
	t.Policy_coverage, _ = types.NewDecimalFromString(policy_coverageNull.String)
	t.Insurance_type = types.NewCode(insurance_typeNull.String)
	t.Last_date_modified, _ = types.NewDateFromString(last_date_modifiedNull.String)
	t.Insurance_vendor_no = types.NewCode(insurance_vendor_noNull.String)
	t.Fa_class_code = types.NewCode(fa_class_codeNull.String)
	t.Fa_subclass_code = types.NewCode(fa_subclass_codeNull.String)
	t.Fa_location_code = types.NewCode(fa_location_codeNull.String)
	t.Department_code = types.NewCode(department_codeNull.String)
	t.Project_code = types.NewCode(project_codeNull.String)
	t.Location_code = types.NewCode(location_codeNull.String)
	t.Blocked = blockedBool.Bool
	t.Description = types.NewText(descriptionNull.String)
	t.Search_description = types.NewCode(search_descriptionNull.String)
	t.No_series = types.NewCode(no_seriesNull.String)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *Insurance) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.No,
		t.Effective_date,
		t.Policy_no,
		t.Annual_premium,
		t.Policy_coverage,
		t.Insurance_type,
		t.Last_date_modified,
		t.Insurance_vendor_no,
		t.Fa_class_code,
		t.Fa_subclass_code,
		t.Fa_location_code,
		t.Department_code,
		t.Project_code,
		t.Location_code,
		t.Blocked,
		t.Description,
		t.Search_description,
		t.No_series,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (no, effective_date, policy_no, annual_premium, policy_coverage, insurance_type, last_date_modified, insurance_vendor_no, fa_class_code, fa_subclass_code, fa_location_code, department_code, project_code, location_code, blocked, description, search_description, no_series) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Insurance: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(InsuranceTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *Insurance) InsertAll(records []*Insurance, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.No,
			r.Effective_date,
			r.Policy_no,
			r.Annual_premium,
			r.Policy_coverage,
			r.Insurance_type,
			r.Last_date_modified,
			r.Insurance_vendor_no,
			r.Fa_class_code,
			r.Fa_subclass_code,
			r.Fa_location_code,
			r.Department_code,
			r.Project_code,
			r.Location_code,
			r.Blocked,
			r.Description,
			r.Search_description,
			r.No_series,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)
	columns := []string{"no", "effective_date", "policy_no", "annual_premium", "policy_coverage", "insurance_type", "last_date_modified", "insurance_vendor_no", "fa_class_code", "fa_subclass_code", "fa_location_code", "department_code", "project_code", "location_code", "blocked", "description", "search_description", "no_series"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *Insurance) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			setClauses = append(setClauses, "no = ?")
			values = append(values, t.No)
		}
		if t.hasFieldChanged("effective_date") {
			setClauses = append(setClauses, "effective_date = ?")
			values = append(values, t.Effective_date)
		}
		if t.hasFieldChanged("policy_no") {
			setClauses = append(setClauses, "policy_no = ?")
			values = append(values, t.Policy_no)
		}
		if t.hasFieldChanged("annual_premium") {
			setClauses = append(setClauses, "annual_premium = ?")
			values = append(values, t.Annual_premium)
		}
		if t.hasFieldChanged("policy_coverage") {
			setClauses = append(setClauses, "policy_coverage = ?")
			values = append(values, t.Policy_coverage)
		}
		if t.hasFieldChanged("insurance_type") {
			setClauses = append(setClauses, "insurance_type = ?")
			values = append(values, t.Insurance_type)
		}
		if t.hasFieldChanged("last_date_modified") {
			setClauses = append(setClauses, "last_date_modified = ?")
			values = append(values, t.Last_date_modified)
		}
		if t.hasFieldChanged("insurance_vendor_no") {
			setClauses = append(setClauses, "insurance_vendor_no = ?")
			values = append(values, t.Insurance_vendor_no)
		}
		if t.hasFieldChanged("fa_class_code") {
			setClauses = append(setClauses, "fa_class_code = ?")
			values = append(values, t.Fa_class_code)
		}
		if t.hasFieldChanged("fa_subclass_code") {
			setClauses = append(setClauses, "fa_subclass_code = ?")
			values = append(values, t.Fa_subclass_code)
		}
		if t.hasFieldChanged("fa_location_code") {
			setClauses = append(setClauses, "fa_location_code = ?")
			values = append(values, t.Fa_location_code)
		}
		if t.hasFieldChanged("department_code") {
			setClauses = append(setClauses, "department_code = ?")
			values = append(values, t.Department_code)
		}
		if t.hasFieldChanged("project_code") {
			setClauses = append(setClauses, "project_code = ?")
			values = append(values, t.Project_code)
		}
		if t.hasFieldChanged("location_code") {
			setClauses = append(setClauses, "location_code = ?")
			values = append(values, t.Location_code)
		}
		if t.hasFieldChanged("blocked") {
			setClauses = append(setClauses, "blocked = ?")
			values = append(values, t.Blocked)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("search_description") {
			setClauses = append(setClauses, "search_description = ?")
			values = append(values, t.Search_description)
		}
		if t.hasFieldChanged("no_series") {
			setClauses = append(setClauses, "no_series = ?")
			values = append(values, t.No_series)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "effective_date = ?")
		values = append(values, t.Effective_date)
		setClauses = append(setClauses, "policy_no = ?")
		values = append(values, t.Policy_no)
		setClauses = append(setClauses, "annual_premium = ?")
		values = append(values, t.Annual_premium)
		setClauses = append(setClauses, "policy_coverage = ?")
		values = append(values, t.Policy_coverage)
		setClauses = append(setClauses, "insurance_type = ?")
		values = append(values, t.Insurance_type)
		setClauses = append(setClauses, "last_date_modified = ?")
		values = append(values, t.Last_date_modified)
		setClauses = append(setClauses, "insurance_vendor_no = ?")
		values = append(values, t.Insurance_vendor_no)
		setClauses = append(setClauses, "fa_class_code = ?")
		values = append(values, t.Fa_class_code)
		setClauses = append(setClauses, "fa_subclass_code = ?")
		values = append(values, t.Fa_subclass_code)
		setClauses = append(setClauses, "fa_location_code = ?")
		values = append(values, t.Fa_location_code)
		setClauses = append(setClauses, "department_code = ?")
		values = append(values, t.Department_code)
		setClauses = append(setClauses, "project_code = ?")
		values = append(values, t.Project_code)
		setClauses = append(setClauses, "location_code = ?")
		values = append(values, t.Location_code)
		setClauses = append(setClauses, "blocked = ?")
		values = append(values, t.Blocked)
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "search_description = ?")
		values = append(values, t.Search_description)
		setClauses = append(setClauses, "no_series = ?")
		values = append(values, t.No_series)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.No)
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			renamed = append(renamed, renamedKey{"no", t.oldValues["no"], t.No})
		}
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Insurance: %v\n", err)
		return false
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Insurance: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *Insurance) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.No.Equal(old)
		}
	case "effective_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Effective_date.Equal(old)
		}
	case "policy_no":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Policy_no.Equal(old)
		}
	case "annual_premium":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Annual_premium.Equal(old)
		}
	case "policy_coverage":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Policy_coverage.Equal(old)
		}
	case "insurance_type":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Insurance_type.Equal(old)
		}
	case "last_date_modified":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Last_date_modified.Equal(old)
		}
	case "insurance_vendor_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Insurance_vendor_no.Equal(old)
		}
	case "fa_class_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Fa_class_code.Equal(old)
		}
	case "fa_subclass_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Fa_subclass_code.Equal(old)
		}
	case "fa_location_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Fa_location_code.Equal(old)
		}
	case "department_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Department_code.Equal(old)
		}
	case "project_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Project_code.Equal(old)
		}
	case "location_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Location_code.Equal(old)
		}
	case "blocked":
		if old, ok := oldValue.(bool); ok {
			return t.Blocked != old
		}
		return true // Type mismatch, assume changed
	case "description":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Description.Equal(old)
		}
	case "search_description":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Search_description.Equal(old)
		}
	case "no_series":
		if old, ok := oldValue.(types.Code); ok {
			return !t.No_series.Equal(old)
		}
	}

	return false
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Insurance) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Insurance) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"Comment_Line", false, "no", "table_name", 11}, {"Ins_Coverage_Ledger_Entry", false, "insurance_no", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// Delete removes the record from the database
func (t *Insurance) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.No,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete Insurance: %v\n", err)
		return false
	}
	return true
}

// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *Insurance) CalcFields(fieldNames ...string) {
	// If no field names specified, calculate all FlowFields
	if len(fieldNames) == 0 {
		t.calcFlowField_total_value_insured()
		t.calcFlowField_comment()
		return
	}

	// Calculate only specified fields
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "total_value_insured":
			t.calcFlowField_total_value_insured()
		case "comment":
			t.calcFlowField_comment()
		}
	}
}

// calcFlowField_total_value_insured calculates the total_value_insured FlowField
// CalcFormula: Sum(InsCoverageLedgerEntry.amount)
func (t *Insurance) calcFlowField_total_value_insured() {
	t.Total_value_insured = t.calcSum_total_value_insured()
}

// calcFlowField_comment calculates the comment FlowField
// CalcFormula: Exist(CommentLine.line_no)
func (t *Insurance) calcFlowField_comment() {
	t.Comment = t.calcCount_comment() > 0
}

// CalcFieldsForRecords calculates FlowFields for many records at once (list pages):
// one grouped query per FlowField instead of one query per record. records are
// ToMap() results; each gets its FlowField values under the field name. With no
// field names, all FlowFields are calculated.
func (t *Insurance) CalcFieldsForRecords(records []map[string]interface{}, fieldNames ...string) {
	if len(records) == 0 {
		return
	}
	if len(fieldNames) == 0 {
		fieldNames = t.GetFlowFields()
	}
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "total_value_insured":
			t.calcForRecords_total_value_insured(records)
		case "comment":
			t.calcForRecords_comment(records)
		}
	}
}

// calcForRecords_total_value_insured calculates the total_value_insured FlowField for a set of records
// CalcFormula: Sum(InsCoverageLedgerEntry.amount)
func (t *Insurance) calcForRecords_total_value_insured(records []map[string]interface{}) {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, InsCoverageLedgerEntryTableName), false
	tableName, useSIFT = sift.TableName(t.company, InsCoverageLedgerEntryTableName, "insurance_disposed_date"), true
	if t.Date_filter != "" {
		// A FlowFilter is set: the key must contain the filtered fields too
		tableName, useSIFT = sift.TableName(t.company, InsCoverageLedgerEntryTableName, "insurance_disposed_date"), true
	}
	_ = useSIFT

	// Distinct key values of the records
	seen := make(map[string]bool, len(records))
	var keys []interface{}
	for _, rec := range records {
		k := fmt.Sprint(rec["no"])
		if !seen[k] {
			seen[k] = true
			keys = append(keys, rec["no"])
		}
	}

	// One grouped query for the keys (IN list). With more keys than chunkSize (a long
	// list) one grouped query over the whole source table instead: much cheaper than
	// many IN queries, and it keeps the bind parameters bounded.
	values := make(map[string]types.Decimal, len(keys))
	const chunkSize = 500
	chunks := [][]interface{}{nil} // nil chunk: no IN filter, all keys
	if len(keys) <= chunkSize {
		chunks = [][]interface{}{keys}
	}
	for _, chunk := range chunks {

		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "disposed_fa = ?")
		args = append(args, false)
		if t.Date_filter != "" {
			// FlowFilter date_filter applied to posting_date (validated by SetFlowFilter)
			if clause, filterArgs, _ := flowfilter.Clause("posting_date", flowfilter.KindDate, t.Date_filter); clause != "" {
				whereClauses = append(whereClauses, clause)
				args = append(args, filterArgs...)
			}
		}
		if chunk != nil {
			whereClauses = append(whereClauses, "insurance_no IN ("+strings.TrimSuffix(strings.Repeat("?, ", len(chunk)), ", ")+")")
			args = append(args, chunk...)
		}
		whereClause := "1=1"
		if len(whereClauses) > 0 {
			whereClause = strings.Join(whereClauses, " AND ")
		}
		query := fmt.Sprintf(`SELECT insurance_no, COALESCE(SUM(amount), 0) FROM "%s" WHERE %s GROUP BY insurance_no`, tableName, whereClause)
		query = t.convertPlaceholders(query, len(args))

		rows, err := t.db.Query(query, args...)
		if err != nil {
			fmt.Printf("Error: Failed to calculate total_value_insured: %v\n", err)
			return
		}
		for rows.Next() {
			var key string
			var sumStr string
			if err := rows.Scan(&key, &sumStr); err == nil {
				values[key], _ = types.NewDecimalFromString(sumStr)
			}
		}
		_ = rows.Close()
	}

	// Records without matching entries get zero
	for _, rec := range records {
		v, ok := values[fmt.Sprint(rec["no"])]
		if !ok {
			v = types.ZeroDecimal()
		}
		rec["total_value_insured"] = v.String()
	}
}

// calcForRecords_comment calculates the comment FlowField for a set of records
// CalcFormula: Exist(CommentLine.line_no)
func (t *Insurance) calcForRecords_comment(records []map[string]interface{}) {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, CommentLineTableName), false
	_ = useSIFT

	// Distinct key values of the records
	seen := make(map[string]bool, len(records))
	var keys []interface{}
	for _, rec := range records {
		k := fmt.Sprint(rec["no"])
		if !seen[k] {
			seen[k] = true
			keys = append(keys, rec["no"])
		}
	}

	// One grouped query for the keys (IN list). With more keys than chunkSize (a long
	// list) one grouped query over the whole source table instead: much cheaper than
	// many IN queries, and it keeps the bind parameters bounded.
	values := make(map[string]int, len(keys))
	const chunkSize = 500
	chunks := [][]interface{}{nil} // nil chunk: no IN filter, all keys
	if len(keys) <= chunkSize {
		chunks = [][]interface{}{keys}
	}
	for _, chunk := range chunks {

		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "table_name = ?")
		args = append(args, 11)
		if chunk != nil {
			whereClauses = append(whereClauses, "no IN ("+strings.TrimSuffix(strings.Repeat("?, ", len(chunk)), ", ")+")")
			args = append(args, chunk...)
		}
		whereClause := "1=1"
		if len(whereClauses) > 0 {
			whereClause = strings.Join(whereClauses, " AND ")
		}
		agg := "COUNT(*)"
		if useSIFT {
			agg = "COALESCE(SUM(cnt), 0)" // the totals hold the entry count per key value
		}
		query := fmt.Sprintf(`SELECT no, %s FROM "%s" WHERE %s GROUP BY no`, agg, tableName, whereClause)
		query = t.convertPlaceholders(query, len(args))

		rows, err := t.db.Query(query, args...)
		if err != nil {
			fmt.Printf("Error: Failed to calculate comment: %v\n", err)
			return
		}
		for rows.Next() {
			var key string
			var count int
			if err := rows.Scan(&key, &count); err == nil {
				values[key] = count
			}
		}
		_ = rows.Close()
	}

	// Records without matching entries get zero
	for _, rec := range records {
		rec["comment"] = values[fmt.Sprint(rec["no"])] > 0
	}
}

// Helper methods for FlowField calculations

func (t *Insurance) calcSum_total_value_insured() types.Decimal {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, InsCoverageLedgerEntryTableName), false
	tableName, useSIFT = sift.TableName(t.company, InsCoverageLedgerEntryTableName, "insurance_disposed_date"), true
	if t.Date_filter != "" {
		// A FlowFilter is set: the key must contain the filtered fields too
		tableName, useSIFT = sift.TableName(t.company, InsCoverageLedgerEntryTableName, "insurance_disposed_date"), true
	}
	_ = useSIFT

	// Build WHERE clause from FlowFilters
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "insurance_no = ?")
	args = append(args, t.No)
	whereClauses = append(whereClauses, "disposed_fa = ?")
	args = append(args, false)
	if t.Date_filter != "" {
		// FlowFilter date_filter applied to posting_date (validated by SetFlowFilter)
		if clause, filterArgs, _ := flowfilter.Clause("posting_date", flowfilter.KindDate, t.Date_filter); clause != "" {
			whereClauses = append(whereClauses, clause)
			args = append(args, filterArgs...)
		}
	}

	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}

	query := fmt.Sprintf(`SELECT COALESCE(SUM(amount), 0) FROM "%s" WHERE %s`, tableName, whereClause)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	var sumStr string
	err := t.db.QueryRow(query, args...).Scan(&sumStr)
	if err != nil {
		fmt.Printf("Error: Failed to calculate sum for total_value_insured: %v\n", err)
		return types.ZeroDecimal()
	}

	sum, _ := types.NewDecimalFromString(sumStr)
	return sum
}

func (t *Insurance) calcCount_comment() int {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, CommentLineTableName), false
	_ = useSIFT

	// Build WHERE clause from FlowFilters
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "table_name = ?")
	args = append(args, 11)
	whereClauses = append(whereClauses, "no = ?")
	args = append(args, t.No)

	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}

	agg := "COUNT(*)"
	if useSIFT {
		agg = "COALESCE(SUM(cnt), 0)" // the totals hold the entry count per key value
	}
	query := fmt.Sprintf(`SELECT %s FROM "%s" WHERE %s`, agg, tableName, whereClause)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	var count int
	err := t.db.QueryRow(query, args...).Scan(&count)
	if err != nil {
		fmt.Printf("Error: Failed to calculate count for comment: %v\n", err)
		return 0
	}

	return count
}

// ========================================
// Filtering and Search
// ========================================

// insuranceFilterCondition represents a filter on a field
type insuranceFilterCondition struct {
	fieldName    string
	minValue     interface{}
	maxValue     interface{}
	filterExpr   string // For complex SetFilter expressions
	isExpression bool   // True if using filterExpr instead of min/max
	invalidField bool   // Filter on an unknown field: matches no rows (fail closed)
	blankDate    bool   // A date range from the blank date: blank dates (NULL) match too
	flowField    string // Filter on a FlowField (filterExpr applied to its subquery)
}

// SetRange sets a range filter on a field
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
//	SetRange("No") - removes the filter on the field
func (t *Insurance) SetRange(fieldName string, values ...interface{}) {
	if t.filters == nil {
		t.filters = make(map[string]*insuranceFilterCondition)
	}

	var minValue, maxValue interface{}

	switch len(values) {
	case 0:
		if column, ok := t.columnName(fieldName); ok {
			delete(t.filters, column)
		}
		delete(t.filters, fieldName)
		return
	case 1:
		// Exact match: SetRange("No", "10000")
		minValue = values[0]
		maxValue = values[0]
	case 2:
		// Range: SetRange("No", "10000", "20000")
		minValue = values[0]
		maxValue = values[1]
	default:
		fmt.Printf("Error: SetRange requires 1 or 2 values, got %d\n", len(values))
		return
	}

	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetRange on unknown field %q of Insurance\n", fieldName)
		t.filters[fieldName] = &insuranceFilterCondition{invalidField: true}
		return
	}

	// Blank dates are stored as NULL and come before every date: a range from the blank date
	// (or the blank date itself) matches them; a range up to the blank date (0D..0D) is the
	// blank date only
	blankDate := false
	if d, ok := values[0].(types.Date); ok && d.IsZero() {
		blankDate = true
		minValue = nil
		if len(values) == 1 {
			maxValue = nil
		}
		if to, ok := maxValue.(types.Date); ok && to.IsZero() {
			maxValue = nil
		}
	}

	t.filters[column] = &insuranceFilterCondition{
		fieldName: column,
		minValue:  minValue,
		maxValue:  maxValue,
		blankDate: blankDate,
	}
}

// SetFilter sets a complex filter expression on a field
// Supports filter syntax: "100..200|500" (range OR exact value)
// Operators: .. (range), | (OR), & (AND), * (wildcard), <> (not equal)
// Example: customer.SetFilter("No", "001..003|005")
func (t *Insurance) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*insuranceFilterCondition)
	}
	if _, ok := t.FlowFieldFilterKind(fieldName); ok {
		// A FlowField is not a column: the filter applies to its subquery (flowFieldExpr)
		name := strings.ToLower(fieldName)
		t.filters["flowfield:"+name] = &insuranceFilterCondition{
			flowField:    name,
			filterExpr:   filterExpr,
			isExpression: true,
		}
		return
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of Insurance\n", fieldName)
		t.filters[fieldName] = &insuranceFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &insuranceFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

// FlowFieldFilterKind reports whether a list can be filtered on FlowField field (Sum and
// Count FlowFields: SETFILTER on a FlowField) and the kind of its values.
func (t *Insurance) FlowFieldFilterKind(field string) (flowfilter.Kind, bool) {
	switch strings.ToLower(field) {
	case "total_value_insured":
		return flowfilter.KindDecimal, true
	}
	return "", false
}

// flowFieldExpr is the SQL expression computing FlowField field for each row of a query
// on this table: a correlated subquery reading the source like CalcFieldsForRecords (the
// SIFT totals of a covering key, else the entries), with the FlowFilters set on t.
func (t *Insurance) flowFieldExpr(field string) (string, []interface{}) {
	outer := "\"" + fmt.Sprintf("%s$%s", t.company, InsuranceTableName) + "\""
	_ = outer
	switch strings.ToLower(field) {
	case "total_value_insured":
		// Source: the SIFT totals table of a key covering the filters, else the entries
		tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, InsCoverageLedgerEntryTableName), false
		tableName, useSIFT = sift.TableName(t.company, InsCoverageLedgerEntryTableName, "insurance_disposed_date"), true
		if t.Date_filter != "" {
			// A FlowFilter is set: the key must contain the filtered fields too
			tableName, useSIFT = sift.TableName(t.company, InsCoverageLedgerEntryTableName, "insurance_disposed_date"), true
		}
		_ = useSIFT
		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "insurance_no = "+outer+".no")
		whereClauses = append(whereClauses, "disposed_fa = ?")
		args = append(args, false)
		if t.Date_filter != "" {
			// FlowFilter date_filter applied to posting_date (validated by SetFlowFilter)
			if clause, filterArgs, _ := flowfilter.Clause("posting_date", flowfilter.KindDate, t.Date_filter); clause != "" {
				whereClauses = append(whereClauses, clause)
				args = append(args, filterArgs...)
			}
		}
		where := "1=1"
		if len(whereClauses) > 0 {
			where = strings.Join(whereClauses, " AND ")
		}
		agg := "COALESCE(SUM(amount), 0)"
		return "(SELECT " + agg + " FROM \"" + tableName + "\" WHERE " + where + ")", args
	}
	return "NULL", nil
}

// SetCurrentKey sets the sort order for queries
// Unknown fields are ignored (the primary key order is used if none remain).
// Example: customer.SetCurrentKey("City", "Name")
func (t *Insurance) SetCurrentKey(fields ...string) {
	t.orderByFields = nil
	for _, field := range fields {
		// A Sum/Count FlowField sorts on its calculated value (flowFieldExpr, see getOrderByClause)
		if _, ok := t.FlowFieldFilterKind(field); ok {
			t.orderByFields = append(t.orderByFields, "flowfield:"+strings.ToLower(field))
			continue
		}
		column, ok := t.columnName(field)
		if !ok {
			fmt.Printf("Error: SetCurrentKey on unknown field %q of Insurance\n", field)
			continue
		}
		t.orderByFields = append(t.orderByFields, column)
	}
}

// SetAscending sets the sort direction of the current key (Ascending).
// The default is ascending.
