// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *Insurance) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, effective_date, policy_no, annual_premium, policy_coverage, insurance_type, last_date_modified, insurance_vendor_no, fa_class_code, fa_subclass_code, fa_location_code, department_code, project_code, location_code, blocked, description, search_description, no_series FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Insurance: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *Insurance) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var noNull sql.NullString
		var effective_dateNull sql.NullString
		var policy_noNull sql.NullString
		var annual_premiumNull sql.NullString
		var policy_coverageNull sql.NullString
		var insurance_typeNull sql.NullString
		var last_date_modifiedNull sql.NullString
		var insurance_vendor_noNull sql.NullString
		var fa_class_codeNull sql.NullString
		var fa_subclass_codeNull sql.NullString
		var fa_location_codeNull sql.NullString
		var department_codeNull sql.NullString
		var project_codeNull sql.NullString
		var location_codeNull sql.NullString
		var blockedBool sql.NullBool
		var descriptionNull sql.NullString
		var search_descriptionNull sql.NullString
		var no_seriesNull sql.NullString

		err := t.currentRows.Scan(
			&noNull,
			&effective_dateNull,
			&policy_noNull,
			&annual_premiumNull,
			&policy_coverageNull,
			&insurance_typeNull,
			&last_date_modifiedNull,
			&insurance_vendor_noNull,
			&fa_class_codeNull,
			&fa_subclass_codeNull,
			&fa_location_codeNull,
			&department_codeNull,
			&project_codeNull,
			&location_codeNull,
			&blockedBool,
			&descriptionNull,
			&search_descriptionNull,
			&no_seriesNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Insurance record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.No = types.NewCode(noNull.String)
		t.Effective_date, _ = types.NewDateFromString(effective_dateNull.String)
		t.Policy_no = types.NewText(policy_noNull.String)
		t.Annual_premium, _ = types.NewDecimalFromString(annual_premiumNull.String)
		t.Policy_coverage, _ = types.NewDecimalFromString(policy_coverageNull.String)
		t.Insurance_type = types.NewCode(insurance_typeNull.String)
		t.Last_date_modified, _ = types.NewDateFromString(last_date_modifiedNull.String)
		t.Insurance_vendor_no = types.NewCode(insurance_vendor_noNull.String)
		t.Fa_class_code = types.NewCode(fa_class_codeNull.String)
		t.Fa_subclass_code = types.NewCode(fa_subclass_codeNull.String)
		t.Fa_location_code = types.NewCode(fa_location_codeNull.String)
		t.Department_code = types.NewCode(department_codeNull.String)
		t.Project_code = types.NewCode(project_codeNull.String)
		t.Location_code = types.NewCode(location_codeNull.String)
		t.Blocked = blockedBool.Bool
		t.Description = types.NewText(descriptionNull.String)
		t.Search_description = types.NewCode(search_descriptionNull.String)
		t.No_series = types.NewCode(no_seriesNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *Insurance) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, InsuranceTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, effective_date, policy_no, annual_premium, policy_coverage, insurance_type, last_date_modified, insurance_vendor_no, fa_class_code, fa_subclass_code, fa_location_code, department_code, project_code, location_code, blocked, description, search_description, no_series FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Insurance: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &Insurance{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var noNull sql.NullString
		var effective_dateNull sql.NullString
		var policy_noNull sql.NullString
		var annual_premiumNull sql.NullString
		var policy_coverageNull sql.NullString
		var insurance_typeNull sql.NullString
		var last_date_modifiedNull sql.NullString
		var insurance_vendor_noNull sql.NullString
		var fa_class_codeNull sql.NullString
		var fa_subclass_codeNull sql.NullString
		var fa_location_codeNull sql.NullString
		var department_codeNull sql.NullString
		var project_codeNull sql.NullString
		var location_codeNull sql.NullString
		var blockedBool sql.NullBool
		var descriptionNull sql.NullString
		var search_descriptionNull sql.NullString
		var no_seriesNull sql.NullString

		err := rows.Scan(
			&noNull,
			&effective_dateNull,
			&policy_noNull,
			&annual_premiumNull,
			&policy_coverageNull,
			&insurance_typeNull,
			&last_date_modifiedNull,
			&insurance_vendor_noNull,
			&fa_class_codeNull,
			&fa_subclass_codeNull,
			&fa_location_codeNull,
			&department_codeNull,
			&project_codeNull,
			&location_codeNull,
			&blockedBool,
			&descriptionNull,
			&search_descriptionNull,
			&no_seriesNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Insurance record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.No = types.NewCode(noNull.String)
		record.Effective_date, _ = types.NewDateFromString(effective_dateNull.String)
		record.Policy_no = types.NewText(policy_noNull.String)
		record.Annual_premium, _ = types.NewDecimalFromString(annual_premiumNull.String)
		record.Policy_coverage, _ = types.NewDecimalFromString(policy_coverageNull.String)
		record.Insurance_type = types.NewCode(insurance_typeNull.String)
		record.Last_date_modified, _ = types.NewDateFromString(last_date_modifiedNull.String)
		record.Insurance_vendor_no = types.NewCode(insurance_vendor_noNull.String)
		record.Fa_class_code = types.NewCode(fa_class_codeNull.String)
		record.Fa_subclass_code = types.NewCode(fa_subclass_codeNull.String)
		record.Fa_location_code = types.NewCode(fa_location_codeNull.String)
		record.Department_code = types.NewCode(department_codeNull.String)
		record.Project_code = types.NewCode(project_codeNull.String)
		record.Location_code = types.NewCode(location_codeNull.String)
		record.Blocked = blockedBool.Bool
		record.Description = types.NewText(descriptionNull.String)
		record.Search_description = types.NewCode(search_descriptionNull.String)
		record.No_series = types.NewCode(no_seriesNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Insurance records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
